item.aggregated_output:
1: <#
2: .SYNOPSIS
3:     Shared helpers for codex-consult.ps1 and codex-findings.ps1. Dot-source it:
4: 
5:         . (Join-Path $PSScriptRoot 'codex-consult-common.ps1')
6: 
7: .DESCRIPTION
8:     Dot-sourcing runs this file in the caller's scope, so the $script: variables set
9:     here belong to the calling script. A caller may set $script:ToolName BEFORE
10:     dot-sourcing to change the prefix of Stop-WithError messages.
11: 
12:     Contents:
13:       * text/JSON I/O    Write-Utf8NoBom, Write-JsonFile, Read-SharedText
14:       * errors, git      Stop-WithError, Get-GitOutput, Invoke-GitCapture
15:       * paths            Resolve-RepoRoot, Resolve-CollabRoot, Get-RepoRelativePath
16:       * fingerprints     Get-FileSha256, Get-RevisionInfo, Get-ArtifactHashes
17:       * findings         Read-FindingsFile, Write-FindingsFile, Format-FindingLine,
18:                          Add-ReplyFindings
19:       * structured reply ConvertFrom-StructuredReply, Test-StructuredReply,
20:                          Format-StructuredSection, Format-StructuredStatusLine
21:       * task lock        Enter-TaskLock, Exit-TaskLock
22:       * processes        Stop-ProcessTree, ConvertTo-ProcArg, Format-Argv
23: 
24:     Windows PowerShell 5.1 and PowerShell 7 compatible, no external dependencies.
25:     Keep this file ASCII: Windows PowerShell reads a BOM-less script in the ANSI
26:     code page.
27: #>
28: 
29: # PowerShell 5.1 has no $IsWindows; an undefined variable is $null there.
30: $script:OnWindows = if ($null -ne $IsWindows) { [bool]$IsWindows } else { $true }
31: $script:LegacyPS = ($PSVersionTable.PSVersion.Major -lt 6)
32: $script:Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
33: $script:Invariant = [System.Globalization.CultureInfo]::InvariantCulture
34: if (-not $script:ToolName) { $script:ToolName = 'codex-consult' }
35: 
36: # Closed sets of the consult-reply v1 schema (schemas/consult-reply.schema.json).
37: $script:ReplyFields = @('schema_version', 'verdict', 'verdict_reason', 'reply_markdown', 'findings', 'prior_findings', 'unproven', 'first_run_checklist')
38: $script:FindingFields = @('severity', 'locations', 'claim', 'trigger', 'evidence', 'verification', 'remedy', 'supersedes')
39: $script:Verdicts = @('ACCEPT', 'HOLD', 'REJECT', 'ADVISE')
40: $script:Severities = @('blocker', 'major', 'minor', 'note')
41: $script:EvidenceKinds = @('read-code', 'ran-command', 'inferred', 'assumed')
42: $script:PriorStatuses = @('fixed', 'still-open', 'not-checked', 'unknown-id')
43: # Coordinator-owned statuses of a tracked finding (findings.json).
44: $script:FindingStatuses = @('proposed', 'implemented', 'verified', 'rejected', 'wontfix', 'superseded')
45: $script:OpenStatuses = @('proposed', 'implemented')
46: 
47: # ----------------------------------------------------------------------------- text + JSON I/O
48: 
49: function Write-Utf8NoBom {
50:     param([string]$Path, [string]$Text)
51:     [IO.File]::WriteAllText($Path, $Text, $script:Utf8NoBom)
52: }
53: 
54: # JSON files (sessions.json, findings.json): UTF-8 without BOM, LF line endings.
55: # -InputObject, never the pipeline: piping an array into ConvertTo-Json unrolls it.
56: function Write-JsonFile {
57:     param([string]$Path, $Object)
58:     $json = ConvertTo-Json -InputObject $Object -Depth 20
59:     Write-Utf8NoBom -Path $Path -Text (($json -replace "`r`n", "`n") + "`n")
60: }
61: 
62: # Start-Process holds the stdout/stderr redirection handles for a short while after
63: # the child exits, so a plain Get-Content can fail with "the process cannot access
64: # the file ... because it is being used by another process" - observed on a
65: # fast-failing codex run. Read with FileShare.ReadWrite and retry briefly.
66: function Read-SharedText {
67:     param([string]$Path)
68:     if (-not (Test-Path -LiteralPath $Path)) { return '' }
69:     for ($attempt = 1; $attempt -le 6; $attempt++) {
70:         try {
71:             $fs = New-Object System.IO.FileStream($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
72:             try {
73:                 $sr = New-Object System.IO.StreamReader($fs, (New-Object System.Text.UTF8Encoding($false)), $true)
74:                 try { return $sr.ReadToEnd() } finally { $sr.Dispose() }
75:             } finally { $fs.Dispose() }
76:         } catch {
77:             Start-Sleep -Milliseconds 250
78:         }
79:     }
80:     return ''
81: }
82: 
83: function Get-IsoTimestamp {
84:     param([datetime]$When = (Get-Date))
85:     return $When.ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant)
86: }
87: 
88: function Stop-WithError {
89:     param([string]$Message)
90:     Write-Host "$($script:ToolName): $Message" -ForegroundColor Red
91:     exit 1
92: }
93: 
94: # ----------------------------------------------------------------------------- git
95: 
96: # Git is optional and every call here is allowed to fail (no repo, no commits yet,
97: # git not installed). Windows PowerShell turns a native command's stderr into a
98: # terminating NativeCommandError while $ErrorActionPreference is 'Stop', so relax it
99: # for the duration of the call and report failure as $null.
100: function Get-GitOutput {
101:     param([string]$Root, [string[]]$GitArgs)
102:     $all = @('-C', $Root) + $GitArgs
103:     $previous = $ErrorActionPreference
104:     $ErrorActionPreference = 'Continue'
105:     try {
106:         $out = & git @all 2>$null
107:         if ($LASTEXITCODE -ne 0) { return $null }
108:         return $out
109:     } catch {
110:         return $null
111:     } finally {
112:         $ErrorActionPreference = $previous
113:     }
114: }
115: 
116: # Argument quoting: bare token when it is safe, otherwise wrap in double quotes and
117: # double any embedded quote. This is the Windows CRT rule, which is also what
118: # .NET's Process argument parser implements on macOS/Linux, so one form serves both.
119: # It is what survives the npm codex.cmd shim on Windows.
120: function ConvertTo-ProcArg {
121:     param([string]$Value)
122:     if ($Value -eq '-') { return $Value }
123:     if ($Value -match '^[A-Za-z0-9_.\-:\\/=]+$') { return $Value }
124:     return '"' + ($Value -replace '"', '""') + '"'
125: }
126: 
127: # Human-readable argv for the record in sessions.json.
128: function Format-Argv {
129:     param([string[]]$Argv)
130:     $parts = $Argv | ForEach-Object {
131:         if ($_ -match '\s') { '"' + $_ + '"' } else { $_ }
132:     }
133:     return ($parts -join ' ')
134: }
135: 
136: # Runs git with the output captured as raw BYTES (NUL-separated `-z` output must not
137: # go through PowerShell's line splitting or a console code page). stdin is not
138: # redirected: on .NET Framework the child's stdin writer can emit a UTF-8 preamble
139: # (chcp 65001), so paths travel as arguments instead. Returns $null when git cannot
140: # be started, else { ExitCode; Bytes }.
141: function Invoke-GitCapture {
142:     param([string]$Root, [string[]]$GitArgs)
143:     try {
144:         $psi = New-Object System.Diagnostics.ProcessStartInfo
145:         $psi.FileName = 'git'
146:         $psi.WorkingDirectory = $Root
147:         $psi.UseShellExecute = $false
148:         $psi.CreateNoWindow = $true
149:         $psi.RedirectStandardOutput = $true
150:         $psi.RedirectStandardError = $true
151:         if ($null -ne $psi.PSObject.Properties['ArgumentList']) {
152:             # .NET Core / PowerShell 7: no quoting rules to get wrong (paths may hold
153:             # quotes or newlines outside Windows).
154:             foreach ($a in $GitArgs) { $psi.ArgumentList.Add($a) }
155:         } else {
156:             # .NET Framework = Windows, where paths cannot contain '"' or newlines.
157:             $psi.Arguments = (($GitArgs | ForEach-Object { ConvertTo-ProcArg $_ }) -join ' ')
158:         }
159:         $p = [System.Diagnostics.Process]::Start($psi)
160:         try {
161:             $ms = New-Object System.IO.MemoryStream
162:             $copy = $p.StandardOutput.BaseStream.CopyToAsync($ms)
163:             $err = $p.StandardError.ReadToEndAsync()
164:             $p.WaitForExit()
165:             $copy.Wait()
166:             $null = $err.Wait(5000)
167:             return [pscustomobject]@{ ExitCode = $p.ExitCode; Bytes = $ms.ToArray() }
168:         } finally {
169:             $p.Dispose()
170:         }
171:     } catch {
172:         return $null
173:     }
174: }
175: 
176: # ----------------------------------------------------------------------------- paths
177: 
178: # The working directory of the caller is the project being discussed, not the
179: # directory the scripts live in (a plugin installs them outside the project).
180: function Resolve-RepoRoot {
181:     param([string]$Cwd)
182:     $top = Get-GitOutput -Root $Cwd -GitArgs @('rev-parse', '--show-toplevel')
183:     if ($top) {
184:         $first = ([string]@($top)[0]).Trim()
185:         if ($first -and (Test-Path -LiteralPath $first)) {
186:             return (Resolve-Path -LiteralPath $first).Path
187:         }
188:     }
189:     # Not a git repository: fall back to the current directory.
190:     return $Cwd
191: }
192: 
193: # Relative -CollabDir resolves against the repository root.
194: function Resolve-CollabRoot {
195:     param([string]$RepoRoot, [string]$CollabDir)
196:     $p = $CollabDir
197:     if (-not [IO.Path]::IsPathRooted($p)) { $p = Join-Path $RepoRoot $p }
198:     return [IO.Path]::GetFullPath($p)
199: }
200: 
201: # '/'-separated path of $Path relative to $Root; '' when they are the same
202: # directory; $null when $Path is not under $Root.
203: function Get-RepoRelativePath {
204:     param([string]$Root, [string]$Path)
205:     $cmp = if ($script:OnWindows) { [StringComparison]::OrdinalIgnoreCase } else { [StringComparison]::Ordinal }
206:     $full = [IO.Path]::GetFullPath($Path).TrimEnd([char]'\', [char]'/')
207:     $rootFull = [IO.Path]::GetFullPath($Root).TrimEnd([char]'\', [char]'/')
208:     if ($full.Equals($rootFull, $cmp)) { return '' }
209:     foreach ($sep in @('\', '/')) {
210:         $prefix = $rootFull + $sep
211:         if ($full.StartsWith($prefix, $cmp)) { return $full.Substring($prefix.Length).Replace('\', '/') }
212:     }
213:     return $null
214: }
215: 
216: # ----------------------------------------------------------------------------- hashing + fingerprint
217: 
218: function ConvertTo-HexString {
219:     param([byte[]]$Bytes)
220:     return ([BitConverter]::ToString($Bytes)).Replace('-', '').ToLowerInvariant()
221: }
222: 
223: function Get-Sha256Hex {
224:     param([byte[]]$Bytes)
225:     $sha = [System.Security.Cryptography.SHA256]::Create()
226:     try { return (ConvertTo-HexString $sha.ComputeHash($Bytes)) } finally { $sha.Dispose() }
227: }
228: 
229: # Streams the file, so a large built artifact is not loaded into memory.
230: function Get-FileSha256 {
231:     param([string]$Path)
232:     $fs = New-Object System.IO.FileStream($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
233:     try {
234:         $sha = [System.Security.Cryptography.SHA256]::Create()
235:         try { return (ConvertTo-HexString $sha.ComputeHash([System.IO.Stream]$fs)) } finally { $sha.Dispose() }
236:     } finally { $fs.Dispose() }
237: }
238: 
239: # Manifest framing: fields are separated by single spaces, the path is the rest of
240: # the line, a rename's source follows after a TAB. Escaping backslash, TAB, CR and LF
241: # makes every line unambiguous whatever the file name holds.
242: function ConvertTo-ManifestPath {
243:     param([string]$Path)
244:     return $Path.Replace('\', '\\').Replace("`t", '\t').Replace("`r", '\r').Replace("`n", '\n')
245: }
246: 
247: # Blob ids for the given repo-relative paths (regular files that exist), computed by
248: # `git hash-object -- <paths>` in batches that respect the Windows command-line
249: # limit. Paths travel as arguments, never via --stdin-paths (see Invoke-GitCapture),
250: # so a path holding a newline needs no special case. A batch that fails is retried
251: # one path at a time; a path that still fails gets 'unreadable'.
252: function Get-GitBlobIds {
253:     param([string]$Root, [string[]]$Paths)
254:     $result = @{}
255:     $batches = New-Object System.Collections.Generic.List[object]
256:     $current = New-Object System.Collections.Generic.List[string]
257:     $chars = 0
258:     foreach ($p in $Paths) {
259:         if ($current.Count -gt 0 -and ($chars + $p.Length + 3) -gt 24000) {
260:             $batches.Add($current.ToArray())
261:             $current = New-Object System.Collections.Generic.List[string]
262:             $chars = 0
263:         }
264:         $current.Add($p)
265:         $chars += $p.Length + 3
266:     }
267:     if ($current.Count -gt 0) { $batches.Add($current.ToArray()) }
268:     foreach ($batch in $batches) {
269:         $ids = $null
270:         $run = Invoke-GitCapture -Root $Root -GitArgs (@('hash-object', '--') + $batch)
271:         if ($run -and $run.ExitCode -eq 0) {
272:             $lines = @(($script:Utf8NoBom.GetString($run.Bytes) -split "`n") | ForEach-Object { $_.Trim() } | Where-Object { $_ })
273:             if ($lines.Count -eq $batch.Count) { $ids = $lines }
274:         }
275:         for ($i = 0; $i -lt $batch.Count; $i++) {
276:             if ($ids) { $result[$batch[$i]] = $ids[$i]; continue }
277:             $one = Invoke-GitCapture -Root $Root -GitArgs @('hash-object', '--', $batch[$i])
278:             $id = 'unreadable'
279:             if ($one -and $one.ExitCode -eq 0) {
280:                 $text = $script:Utf8NoBom.GetString($one.Bytes).Trim()
281:                 if ($text) { $id = $text }
282:             }
283:             $result[$batch[$i]] = $id
284:         }
285:     }
286:     return $result
287: }
288: 
289: # Revision fingerprint of the working tree (T2). tree_sha256 is the SHA-256 of a
290: # deterministic manifest:
291: #
292: #     base <full sha, or 'none' before the first commit>
293: #     <XY> <blob id | deleted | dir> <path>[<TAB><rename source>]
294: #
295: # one line per entry of `git status --porcelain=v1 -uall -z` (ignored files are not
296: # listed by git status, so they are outside the fingerprint by definition), sorted by
297: # path (ordinal), LF-joined with a trailing LF. The path is part of every line, so a
298: # rename changes the value even when the content does not. Entries under the
299: # collaboration directory are excluded: the consultation's own output must not move
300: # the fingerprint. A submodule or nested repository is recorded as 'dir' and not
301: # recursed. Every omission is spelled out in fingerprint_note. No git -> tree_sha256
302: # '' and fingerprint_note 'no git'. changed_files and dirty count the manifest
303: # entries, i.e. also without the collaboration directory.
304: # git status runs with --no-optional-locks, so computing a fingerprint never writes
305: # to the repository (not even an index refresh) - -DryRun stays write-free.
306: function Get-RevisionInfo {
307:     param([string]$Root, [string]$CollabRoot = '')
308:     $info = [pscustomobject]@{
309:         base_commit       = 'unknown'
310:         short_sha         = 'unknown'
311:         dirty             = $false
312:         reviewed_revision = 'unknown'
313:         tree_sha256       = ''
314:         changed_files     = 0
315:         fingerprint_note  = 'no git'
316:         manifest          = ''
317:     }
318:     $status = Invoke-GitCapture -Root $Root -GitArgs @('--no-optional-locks', 'status', '--porcelain=v1', '-uall', '-z')
319:     if (-not $status -or $status.ExitCode -ne 0) { return $info }
320: 
321:     $notes = New-Object System.Collections.Generic.List[string]
322:     $head = Get-GitOutput -Root $Root -GitArgs @('rev-parse', '--verify', '-q', 'HEAD')
323:     $base = 'none'
324:     if ($head) {
325:         $base = ([string]@($head)[0]).Trim()
326:         $info.base_commit = $base
327:         $short = Get-GitOutput -Root $Root -GitArgs @('rev-parse', '--short', 'HEAD')
328:         if ($short) { $info.short_sha = ([string]@($short)[0]).Trim() }
329:     } else {
330:         $notes.Add('no commits yet')
331:     }
332: 
333:     $collabRel = $null
334:     if ($CollabRoot) {
335:         $collabRel = Get-RepoRelativePath -Root $Root -Path $CollabRoot
336:         if ($null -eq $collabRel) { $notes.Add('collab dir outside the repository') }
337:         elseif ($collabRel -eq '') { $notes.Add('collab dir is the repository root: nothing excluded'); $collabRel = $null }
338:     }
339:     $cmp = if ($script:OnWindows) { [StringComparison]::OrdinalIgnoreCase } else { [StringComparison]::Ordinal }
340: 
341:     # Parse the NUL-separated entries: "XY <path>", and for a rename or copy the
342:     # source path follows as the next NUL-terminated field.
343:     $tokens = $script:Utf8NoBom.GetString($status.Bytes).Split([char]0)
344:     $entries = New-Object System.Collections.Generic.List[object]
345:     $excluded = 0
346:     $i = 0
347:     while ($i -lt $tokens.Length) {
348:         $tok = $tokens[$i]
349:         $i++
350:         if ($tok.Length -lt 4) { continue }
351:         $xy = $tok.Substring(0, 2)
352:         $path = $tok.Substring(3)
353:         $orig = $null
354:         if ($xy[0] -ceq 'R' -or $xy[0] -ceq 'C' -or $xy[1] -ceq 'R' -or $xy[1] -ceq 'C') {
355:             if ($i -lt $tokens.Length) { $orig = $tokens[$i]; $i++ }
356:         }
357:         if ($collabRel -and ($path.Equals($collabRel, $cmp) -or $path.StartsWith($collabRel + '/', $cmp))) {
358:             $excluded++
359:             continue
360:         }
361:         $entries.Add([pscustomobject]@{ XY = $xy; Path = $path; Orig = $orig; Blob = '' })
362:     }
363: 
364:     $toHash = New-Object System.Collections.Generic.List[string]
365:     $dirs = 0
366:     foreach ($e in $entries) {
367:         $full = [IO.Path]::Combine($Root, $e.Path)
368:         if ([IO.Directory]::Exists($full)) { $e.Blob = 'dir'; $dirs++ }
369:         elseif ([IO.File]::Exists($full)) { $toHash.Add($e.Path) }
370:         else { $e.Blob = 'deleted' }
371:     }
372:     if ($toHash.Count -gt 0) {
373:         $ids = Get-GitBlobIds -Root $Root -Paths $toHash.ToArray()
374:         foreach ($e in $entries) { if (-not $e.Blob) { $e.Blob = $ids[$e.Path] } }
375:     }
376:     $unreadable = @($entries | Where-Object { $_.Blob -eq 'unreadable' }).Count
377: 
378:     $keys = New-Object System.Collections.Generic.List[string]
379:     $lines = New-Object System.Collections.Generic.List[string]
380:     foreach ($e in $entries) {
381:         $line = $e.XY + ' ' + $e.Blob + ' ' + (ConvertTo-ManifestPath $e.Path)
382:         if ($null -ne $e.Orig) { $line += "`t" + (ConvertTo-ManifestPath $e.Orig) }
383:         $keys.Add($e.Path + [char]0 + $line)
384:         $lines.Add($line)
385:     }
386:     $keyArr = $keys.ToArray()
387:     $lineArr = $lines.ToArray()
388:     [Array]::Sort($keyArr, $lineArr, [StringComparer]::Ordinal)
389:     $sb = New-Object System.Text.StringBuilder
390:     [void]$sb.Append("base $base`n")
391:     foreach ($l in $lineArr) { [void]$sb.Append($l + "`n") }
392:     $manifest = $sb.ToString()
393: 
394:     if ($collabRel) { $notes.Add("collab dir '$collabRel' excluded ($excluded entries)") }
395:     $notes.Add('ignored files excluded')
396:     if ($dirs -gt 0) { $notes.Add("submodules not recursed ($dirs directory entries)") }
397:     else { $notes.Add('submodules not recursed') }
398:     if ($unreadable -gt 0) { $notes.Add("$unreadable files unreadable") }
399: 
400:     $info.manifest = $manifest
401:     $info.tree_sha256 = Get-Sha256Hex -Bytes ($script:Utf8NoBom.GetBytes($manifest))
402:     $info.changed_files = $entries.Count
403:     $info.dirty = ($entries.Count -gt 0)
404:     $info.reviewed_revision = $info.short_sha
405:     if ($info.dirty) { $info.reviewed_revision = "$($info.short_sha) + uncommitted" }
406:     $info.fingerprint_note = ($notes.ToArray() -join '; ')
407:     return $info
408: }
409: 
410: # Built artifacts to bind a review to: { path = as given; sha256 }. A missing
411: # artifact stops the run - the caller asked to bind the review to it, silently
412: # skipping it would defeat the binding. Emits one object per artifact; collect the
413: # result with @(...).
414: function Get-ArtifactHashes {
415:     param([string[]]$Paths, [string[]]$Bases)
416:     foreach ($raw in @($Paths)) {
417:         if (-not $raw) { continue }
418:         $resolved = $null
419:         if ([IO.Path]::IsPathRooted($raw)) {
420:             if (Test-Path -LiteralPath $raw -PathType Leaf) { $resolved = $raw }
421:         } else {
422:             foreach ($b in $Bases) {
423:                 $candidate = Join-Path $b $raw
424:                 if (Test-Path -LiteralPath $candidate -PathType Leaf) { $resolved = $candidate; break }
425:             }
426:         }
427:         if (-not $resolved) {
428:             $looked = if ([IO.Path]::IsPathRooted($raw)) { $raw } else { (@($Bases) | Select-Object -Unique) -join ', ' }
429:             Stop-WithError "artifact '$raw' not found (looked in: $looked); a review cannot be bound to a missing artifact."
430:         }
431:         $full = (Resolve-Path -LiteralPath $resolved).Path
432:         [pscustomobject]@{ path = $raw; sha256 = (Get-FileSha256 -Path $full) }
433:     }
434: }
435: 
1074: # ----------------------------------------------------------------------------- task lock
1075: 
1076: # Process start time as a UTC round-trip string. $null: no such process. '': the
1077: # process exists but its start time cannot be read (e.g. another user's process).
1078: function Get-ProcessStartIso {
1079:     param([int]$ProcessId)
1080:     $p = $null
1081:     try { $p = Get-Process -Id $ProcessId -ErrorAction Stop } catch { return $null }
1082:     try { return $p.StartTime.ToUniversalTime().ToString('o', $script:Invariant) } catch { return '' }
1083: }
1084: 
1085: function New-LockRefusal {
1086:     param([string]$Path, [string]$Message)
1087:     return [pscustomobject]@{ Acquired = $false; Path = $Path; Nonce = ''; Note = ''; Message = $Message }
1088: }
1089: 
1090: # One active consultation (or findings update) per task directory:
1091: # <taskDir>/.consult.lock, created atomically with FileMode.CreateNew and holding
1092: # { pid, start_time, nonce, host, task, started }. An existing lock is stale only
1093: # when it was written on THIS host and its pid is gone or now belongs to a process
1094: # with a different start time (pid reuse); a stale lock is removed and CreateNew is
1095: # retried once. A lock from another host is never taken over. Returns
1096: # { Acquired; Path; Nonce; Note; Message } - the caller refuses when not Acquired.
1097: function Enter-TaskLock {
1098:     param([string]$TaskDir, [string]$Task)
1099:     $path = Join-Path $TaskDir '.consult.lock'
1100:     $nonce = [guid]::NewGuid().ToString()
1101:     $hostName = [Environment]::MachineName
1102:     $record = [pscustomobject]@{
1103:         pid        = $PID
1104:         start_time = (Get-ProcessStartIso -ProcessId $PID)
1105:         nonce      = $nonce
1106:         host       = $hostName
1107:         task       = $Task
1108:         started    = (Get-IsoTimestamp)
1109:     }
1110:     $bytes = $script:Utf8NoBom.GetBytes((ConvertTo-Json -InputObject $record -Compress) + "`n")
1111:     $note = ''
1112:     for ($attempt = 1; $attempt -le 2; $attempt++) {
1113:         $fs = $null
1114:         try {
1115:             $fs = [IO.File]::Open($path, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None)
1116:         } catch [System.IO.IOException] {
1117:             $fs = $null
1118:             if (-not [IO.File]::Exists($path)) {
1119:                 return (New-LockRefusal -Path $path -Message "could not create the lock '$path': $($_.Exception.Message)")
1120:             }
1121:         } catch {
1122:             return (New-LockRefusal -Path $path -Message "could not create the lock '$path': $($_.Exception.Message)")
1123:         }
1124:         if ($fs) {
1125:             try { $fs.Write($bytes, 0, $bytes.Length); $fs.Flush() } finally { $fs.Dispose() }
1126:             return [pscustomobject]@{ Acquired = $true; Path = $path; Nonce = $nonce; Note = $note; Message = '' }
1127:         }
1128: 
1129:         $text = Read-SharedText -Path $path
1130:         $holder = $null
1131:         try { if ($text.Trim()) { $holder = ConvertFrom-Json -InputObject $text } } catch { $holder = $null }
1132:         if (-not (Test-IsJsonObject $holder) -or -not $holder.PSObject.Properties['pid']) {
1133:             return (New-LockRefusal -Path $path -Message "the lock '$path' exists but cannot be read (another run may be starting); delete $path only if you know that consultation is dead.")
1134:         }
1135:         $holderPid = 0
1136:         [void][int]::TryParse([string]$holder.pid, [ref]$holderPid)
1137:         $holderHost = [string](Get-PropertyValue $holder 'host' '')
1138:         $holderStart = [string](Get-PropertyValue $holder 'start_time' '')
1139:         $holderStarted = [string](Get-PropertyValue $holder 'started' '?')
1140:         $holderTask = [string](Get-PropertyValue $holder 'task' $Task)
1141:         $stale = $false
1142:         $why = ''
1143:         if ($holderHost -and $holderHost.Equals($hostName, [StringComparison]::OrdinalIgnoreCase)) {
1144:             $live = Get-ProcessStartIso -ProcessId $holderPid
1145:             if ($null -eq $live) { $stale = $true; $why = "pid $holderPid is not running" }
1146:             elseif ($live -and $holderStart -and $live -ne $holderStart) { $stale = $true; $why = "pid $holderPid now belongs to another process (start time differs)" }
1147:         }
1148:         if (-not $stale -or $attempt -ge 2) {
1149:             return (New-LockRefusal -Path $path -Message "another consultation for task '$holderTask' holds the lock (pid $holderPid on $holderHost since $holderStarted); delete $path only if you know that consultation is dead.")
1150:         }
1151:         # Stale: delete it only if it still holds what was judged (another run may
1152:         # have replaced it meanwhile), then retry CreateNew once.
1153:         if ((Read-SharedText -Path $path) -eq $text) {
1154:             try { [IO.File]::Delete($path) } catch {
1155:                 return (New-LockRefusal -Path $path -Message "could not remove the stale lock '$path': $($_.Exception.Message)")
1156:             }
1157:             $note = "removed a stale lock ($why; task '$holderTask', since $holderStarted)."
1158:         }
1159:     }
1160:     return (New-LockRefusal -Path $path -Message "could not acquire the lock '$path'.")
1161: }
