1076: # Process start time as a UTC round-trip string. $null: no such process. '': the
1077: # process exists but its start time cannot be read (e.g. another user's process).
1078: function Get-ProcessStartIso {
1079:     param([int]$ProcessId)
1080:     $p = $null
1081:     try { $p = Get-Process -Id $ProcessId -ErrorAction Stop } catch { return $null }
1082:     try { return $p.StartTime.ToUniversalTime().ToString('o', $script:Invariant) } catch { return '' }
1083: }
1084: 
1085: function New-LockRefusal {
1086:     param([string]$Path, [string]$Message)
1087:     return [pscustomobject]@{ Acquired = $false; Path = $Path; Nonce = ''; Note = ''; Message = $Message }
1088: }
1089: 
1090: # One active consultation (or findings update) per task directory:
1091: # <taskDir>/.consult.lock, created atomically with FileMode.CreateNew and holding
1092: # { pid, start_time, nonce, host, task, started }. An existing lock is stale only
1093: # when it was written on THIS host and its pid is gone or now belongs to a process
1094: # with a different start time (pid reuse); a stale lock is removed and CreateNew is
1095: # retried once. A lock from another host is never taken over. Returns
1096: # { Acquired; Path; Nonce; Note; Message } - the caller refuses when not Acquired.
1097: function Enter-TaskLock {
1098:     param([string]$TaskDir, [string]$Task)
1099:     $path = Join-Path $TaskDir '.consult.lock'
1100:     $nonce = [guid]::NewGuid().ToString()
1101:     $hostName = [Environment]::MachineName
1102:     $record = [pscustomobject]@{
1103:         pid        = $PID
1104:         start_time = (Get-ProcessStartIso -ProcessId $PID)
1105:         nonce      = $nonce
1106:         host       = $hostName
1107:         task       = $Task
1108:         started    = (Get-IsoTimestamp)
1109:     }
1110:     $bytes = $script:Utf8NoBom.GetBytes((ConvertTo-Json -InputObject $record -Compress) + "`n")
1111:     $note = ''
1112:     for ($attempt = 1; $attempt -le 2; $attempt++) {
1113:         $fs = $null
1114:         try {
1115:             $fs = [IO.File]::Open($path, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None)
1116:         } catch [System.IO.IOException] {
1117:             $fs = $null
1118:             if (-not [IO.File]::Exists($path)) {
1119:                 return (New-LockRefusal -Path $path -Message "could not create the lock '$path': $($_.Exception.Message)")
1120:             }
1121:         } catch {
1122:             return (New-LockRefusal -Path $path -Message "could not create the lock '$path': $($_.Exception.Message)")
1123:         }
1124:         if ($fs) {
1125:             try { $fs.Write($bytes, 0, $bytes.Length); $fs.Flush() } finally { $fs.Dispose() }
1126:             return [pscustomobject]@{ Acquired = $true; Path = $path; Nonce = $nonce; Note = $note; Message = '' }
1127:         }
1128: 
1129:         $text = Read-SharedText -Path $path
1130:         $holder = $null
1131:         try { if ($text.Trim()) { $holder = ConvertFrom-Json -InputObject $text } } catch { $holder = $null }
1132:         if (-not (Test-IsJsonObject $holder) -or -not $holder.PSObject.Properties['pid']) {
1133:             return (New-LockRefusal -Path $path -Message "the lock '$path' exists but cannot be read (another run may be starting); delete $path only if you know that consultation is dead.")
1134:         }
1135:         $holderPid = 0
1136:         [void][int]::TryParse([string]$holder.pid, [ref]$holderPid)
1137:         $holderHost = [string](Get-PropertyValue $holder 'host' '')
1138:         $holderStart = [string](Get-PropertyValue $holder 'start_time' '')
1139:         $holderStarted = [string](Get-PropertyValue $holder 'started' '?')
1140:         $holderTask = [string](Get-PropertyValue $holder 'task' $Task)
1141:         $stale = $false
1142:         $why = ''
1143:         if ($holderHost -and $holderHost.Equals($hostName, [StringComparison]::OrdinalIgnoreCase)) {
1144:             $live = Get-ProcessStartIso -ProcessId $holderPid
1145:             if ($null -eq $live) { $stale = $true; $why = "pid $holderPid is not running" }
1146:             elseif ($live -and $holderStart -and $live -ne $holderStart) { $stale = $true; $why = "pid $holderPid now belongs to another process (start time differs)" }
1147:         }
1148:         if (-not $stale -or $attempt -ge 2) {
1149:             return (New-LockRefusal -Path $path -Message "another consultation for task '$holderTask' holds the lock (pid $holderPid on $holderHost since $holderStarted); delete $path only if you know that consultation is dead.")
1150:         }
1151:         # Stale: delete it only if it still holds what was judged (another run may
1152:         # have replaced it meanwhile), then retry CreateNew once.
1153:         if ((Read-SharedText -Path $path) -eq $text) {
1154:             try { [IO.File]::Delete($path) } catch {
1155:                 return (New-LockRefusal -Path $path -Message "could not remove the stale lock '$path': $($_.Exception.Message)")
1156:             }
1157:             $note = "removed a stale lock ($why; task '$holderTask', since $holderStarted)."
1158:         }
1159:     }
1160:     return (New-LockRefusal -Path $path -Message "could not acquire the lock '$path'.")
1161: }
1162: 
1163: # Releases the lock only when it still holds our nonce.
1164: function Exit-TaskLock {
1165:     param($Lock)
1166:     if ($null -eq $Lock -or -not $Lock.Acquired) { return }
1167:     try {
1168:         if (-not [IO.File]::Exists($Lock.Path)) { return }
1169:         $holder = $null
1170:         try { $holder = ConvertFrom-Json -InputObject (Read-SharedText -Path $Lock.Path) } catch { $holder = $null }
1171:         if ((Test-IsJsonObject $holder) -and $holder.PSObject.Properties['nonce'] -and [string]$holder.nonce -eq $Lock.Nonce) {
1172:             [IO.File]::Delete($Lock.Path)
1173:         } else {
1174:             Write-Host "$($script:ToolName): the lock '$($Lock.Path)' no longer holds this run's nonce; left in place." -ForegroundColor Yellow
1175:         }
1176:     } catch { }
1177: }
1178: 
1179: # ----------------------------------------------------------------------------- processes
1180: 
1181: # Descendant pids of $RootId (Windows: CIM; elsewhere: pgrep -P). Best effort.
1182: function Get-DescendantPids {
1183:     param([int]$RootId)
1184:     $found = New-Object System.Collections.Generic.List[int]
1185:     $queue = New-Object System.Collections.Generic.Queue[int]
1186:     $queue.Enqueue($RootId)
1187:     $previous = $ErrorActionPreference
1188:     $ErrorActionPreference = 'Continue'
1189:     try {
1190:         $all = @()
1191:         if ($script:OnWindows) {
1192:             try { $all = @(Get-CimInstance -ClassName Win32_Process -Property ProcessId, ParentProcessId -ErrorAction Stop) } catch { $all = @() }
1193:         }
1194:         while ($queue.Count -gt 0) {
1195:             $cur = $queue.Dequeue()
1196:             $kids = @()
1197:             if ($script:OnWindows) {
1198:                 $kids = @($all | Where-Object { [int]$_.ParentProcessId -eq $cur -and [int]$_.ProcessId -ne $cur } | ForEach-Object { [int]$_.ProcessId })
1199:             } else {
1200:                 try { $kids = @(& pgrep -P $cur 2>$null) } catch { $kids = @() }
1201:             }
1202:             foreach ($k in $kids) {
1203:                 $n = 0
1204:                 if ([int]::TryParse(([string]$k).Trim(), [ref]$n) -and -not $found.Contains($n)) {
1205:                     $found.Add($n)
1206:                     $queue.Enqueue($n)
1207:                 }
1208:             }
1209:         }
1210:     } finally {
1211:         $ErrorActionPreference = $previous
1212:     }
1213:     return , ([int[]]$found.ToArray())
1214: }
1215: 
1216: # Kills the process AND its descendants (the launcher is usually a shim: cmd.exe or
1217: # node in front of the real codex binary). Windows: taskkill /T /F; elsewhere: the
1218: # pgrep -P tree. Best effort; returns the number of descendants still alive after.
1219: function Stop-ProcessTree {
1220:     param($Process)
1221:     if ($null -eq $Process) { return 0 }
1222:     $rootId = $Process.Id
1223:     $descendants = @(Get-DescendantPids -RootId $rootId)
1224:     $previous = $ErrorActionPreference
1225:     $ErrorActionPreference = 'Continue'
1226:     try {
1227:         if ($script:OnWindows) {
1228:             try { & taskkill.exe /PID $rootId /T /F 2>$null | Out-Null } catch { }
1229:         }
1230:         foreach ($d in $descendants) {
1231:             try { Stop-Process -Id $d -Force -ErrorAction SilentlyContinue } catch { }
1232:         }
1233:         try { if (-not $Process.HasExited) { $Process.Kill() } } catch { }
1234:         try { $null = $Process.WaitForExit(10000) } catch { }
1235:     } finally {
1236:         $ErrorActionPreference = $previous
1237:     }
1238:     $alive = 0
1239:     foreach ($d in $descendants) {
1240:         if (Get-Process -Id $d -ErrorAction SilentlyContinue) { $alive++ }
1241:     }
1242:     return $alive
1243: }

449: # ----------------------------------------------------------------------------- lock + run
450: #
451: # Everything from here to the end runs while <task>/.consult.lock is held (not in
452: # -DryRun, which writes nothing at all); the lock is taken BEFORE sessions.json and
453: # findings.json are read and before the handoff number NN and the consult number n
454: # are allocated, and released in `finally` (an `exit` inside `try` still runs it).
455: #
456: # Write order and recovery - sessions.json is the commit point:
457: #   1. handoffs/NN-codex-<slug>.md          header + verbatim reply (+ rendered section)
458: #   2. handoffs/NN-codex-<slug>.reply.json  byte-for-byte copy of Codex's last message
459: #   3. findings.json                        new findings, reviewer checks
460: #   4. sessions.json                        the ledger entry
461: # A crash between 3 and 4 leaves findings whose source.consult has no ledger entry;
462: # `codex-findings.ps1 -List` flags them as ORPHAN. A rerun allocates the next NN
463: # (past every handoff file and every finding id) and the next n (past every ledger
464: # entry and every finding's source.consult), so nothing is overwritten.
465: 
466: $lock = $null
467: if (-not $DryRun) {
468:     [void][IO.Directory]::CreateDirectory($handoffsDir)
469:     $lock = Enter-TaskLock -TaskDir $taskDir -Task $Task
470:     if (-not $lock.Acquired) { Stop-WithError $lock.Message }
471:     if ($lock.Note) { Write-Host "codex-consult: $($lock.Note)" -ForegroundColor Yellow }
472: }
473: 
474: try {
475:     # ------------------------------------------------------------------------- ledgers
476: 
477:     $sessions = $null
478:     if (Test-Path -LiteralPath $sessionsPath) {
479:         try {
480:             $sessions = ConvertFrom-Json -InputObject (Read-SharedText -Path $sessionsPath)
481:         } catch {
482:             Stop-WithError "could not parse '$sessionsPath': $($_.Exception.Message)"
483:         }
484:     } else {
485:         $sessions = [pscustomobject]@{
486:             task_id = $Task
487:             cwd     = $repoRoot
488:             codex   = [pscustomobject]@{
489:                 tool     = $codexVersion
490:                 consults = [object[]]@()
491:             }
492:         }
493:         if (-not $DryRun) { Write-JsonFile -Path $sessionsPath -Object $sessions }
494:     }
495:     if (-not $sessions.PSObject.Properties['codex']) {
496:         $sessions | Add-Member -NotePropertyName 'codex' -NotePropertyValue ([pscustomobject]@{ tool = $codexVersion; consults = [object[]]@() })
497:     }
498:     if (-not $sessions.codex.PSObject.Properties['consults']) {
499:         $sessions.codex | Add-Member -NotePropertyName 'consults' -NotePropertyValue ([object[]]@())
500:     }
501:     $sessions.codex.tool = $codexVersion
502: 
503:     # findings.json is only read in structured mode (-Raw does no findings bookkeeping).
504:     $findingsStore = $null
505:     $openFindings = @()
506:     if (-not $Raw) {
507:         $findingsStore = Read-FindingsFile -Path $findingsPath -Task $Task
508:         $openFindings = @($findingsStore.findings | Where-Object { $script:OpenStatuses -contains [string](Get-PropertyValue $_ 'status' '') })
509:     }
510:     $listedIds = [string[]]@($openFindings | ForEach-Object { [string]$_.id })
511: 
512:     # ------------------------------------------------------------------------- mode + thread
513: 
514:     # Older ledger entries (0.1: `outcome`, no `purpose`, ...) are left untouched; only
515:     # `thread` is read from them.
516:     $consults = @($sessions.codex.consults | Where-Object { $_ })
517:     $knownThread = ''
518:     if ($Thread) {
519:         $knownThread = $Thread.Trim()
520:     } else {
521:         for ($i = $consults.Count - 1; $i -ge 0; $i--) {
522:             $c = $consults[$i]
523:             if ($c.PSObject.Properties['thread'] -and $c.thread) { $knownThread = [string]$c.thread; break }
524:         }
525:     }
526: 
527:     if (-not $Mode) {
528:         if ($knownThread) { $Mode = 'fork' } else { $Mode = 'new' }
529:     }
530:     if ($Mode -ne 'new' -and -not $knownThread) {
531:         Stop-WithError "-Mode $Mode needs a thread: pass -Thread <uuid>, or make sure '$sessionsPath' has codex.consults[].thread."
532:     }
533:     $parentThread = ''
534:     if ($Mode -ne 'new') { $parentThread = $knownThread }
535: 
536:     # ------------------------------------------------------------------------- numbering
537: 
538:     # Consult number n: past every ledger entry and every finding's source.consult
539:     # (an orphan left by a crash keeps its number).
540:     $consultN = $consults.Count
541:     foreach ($c in $consults) {
542:         $v = 0
543:         if ($c.PSObject.Properties['n'] -and [int]::TryParse([string]$c.n, [ref]$v) -and $v -gt $consultN) { $consultN = $v }
544:     }
545:     if ($findingsStore) {
546:         foreach ($f in $findingsStore.findings) {
547:             $src = Get-PropertyValue $f 'source' $null
548:             $v = 0
549:             if ($src -and [int]::TryParse([string](Get-PropertyValue $src 'consult' ''), [ref]$v) -and $v -gt $consultN) { $consultN = $v }
550:         }
551:     }
552:     $consultN++
553: 
554:     # Handoff number NN: past every handoff file (two OR MORE digits, so 100-... is
555:     # seen) and every finding id F<NN>-<k>.
556:     $maxN = 0
557:     if (Test-Path -LiteralPath $handoffsDir) {
558:         foreach ($file in @(Get-ChildItem -LiteralPath $handoffsDir -File -ErrorAction SilentlyContinue)) {
559:             $v = 0
560:             if ($file.Name -match '^(\d{2,})-' -and [int]::TryParse($Matches[1], [ref]$v) -and $v -gt $maxN) { $maxN = $v }
561:         }
562:     }
563:     if ($findingsStore) {
564:         foreach ($f in $findingsStore.findings) {
565:             $v = 0
566:             if ([string](Get-PropertyValue $f 'id' '') -match '^F(\d{2,})-\d+$' -and [int]::TryParse($Matches[1], [ref]$v) -and $v -gt $maxN) { $maxN = $v }
567:         }
568:     }
569:     $nn = '{0:D2}' -f ($maxN + 1)
570:     # NB: PowerShell variable names are case-insensitive - never call these $replyName,
571:     # that would silently clobber the -ReplyName parameter.
572:     $replyFileName = "$nn-codex-$ReplyName.md"
573:     $eventsFileName = "$nn-codex-$ReplyName.events.jsonl"
574:     $replyJsonFileName = "$nn-codex-$ReplyName.reply.json"
575:     $replyPath = Join-Path $handoffsDir $replyFileName
758:     Write-Utf8NoBom -Path $promptPath -Text $promptText
759: 
760:     $startedAt = Get-Date
761:     $stopwatch = [System.Diagnostics.Stopwatch]::StartNew()
762:     $exitCode = -1
763:     $bridgeOutcome = ''
764:     $argStr = (($argv | ForEach-Object { ConvertTo-ProcArg $_ }) -join ' ')
765: 
766:     try {
767:         $proc = Start-Process -FilePath $codexExePath -ArgumentList $argStr `
768:             -WorkingDirectory $repoRoot -NoNewWindow -PassThru `
769:             -RedirectStandardOutput $eventsPath `
770:             -RedirectStandardError $stderrPath `
771:             -RedirectStandardInput $promptPath
772:         # PS 5.1: touching .Handle before the process exits caches it, otherwise
773:         # .ExitCode comes back empty on a -PassThru process.
774:         if ($script:LegacyPS) { try { $null = $proc.Handle } catch { } }
775:         $finished = $proc.WaitForExit($TimeoutSec * 1000)
776:         if (-not $finished) {
777:             # The launcher is usually a shim (codex.cmd -> node -> codex.exe): kill
778:             # the whole tree, or the real codex keeps running after we give up.
779:             $survivors = Stop-ProcessTree -Process $proc
780:             $bridgeOutcome = "failed: timeout after $TimeoutSec s (process tree killed)"
781:             if ($survivors -gt 0) { $bridgeOutcome = "failed: timeout after $TimeoutSec s (process tree killed; $survivors processes survived)" }
782:         } else {
783:             $exitCode = $proc.ExitCode
784:         }
785:     } catch {
786:         $bridgeOutcome = "failed: could not start codex - $($_.Exception.Message)"
787:     }
788:     $stopwatch.Stop()
789:     $wallSeconds = [math]::Round($stopwatch.Elapsed.TotalSeconds, 1)
790: 
791:     $revAfter = Get-RevisionInfo -Root $repoRoot -CollabRoot $collabRoot
792:     $treeChanged = ($revBefore.tree_sha256 -ne $revAfter.tree_sha256)
793: 
794:     $stderrText = Read-SharedText -Path $stderrPath
795:     $rawReply = (Read-SharedText -Path $lastMsgPath).Trim()
796: 
797:     # thread id - never let a parse/IO problem here swallow the sessions.json record
798:     $threadId = ''
799:     $threadSource = 'unknown'
800:     try {
801:         $threadId = Get-ThreadIdFromEvents -Path $eventsPath
802:         if ($threadId) {
803:             $threadSource = 'events'
804:         } else {
805:             $threadId = Get-ThreadIdFromRollout -StartedAt $startedAt
806:             if ($threadId) { $threadSource = 'rollout' }
807:         }
808:     } catch {
809:         $threadId = ''
810:         $threadSource = 'unknown'
811:     }
812: 
813:     $eventError = ''
814:     try { $eventError = Get-ErrorFromEvents -Path $eventsPath } catch { $eventError = '' }
815:     $usage = $null
816:     try { $usage = Get-UsageFromEvents -Path $eventsPath } catch { $usage = $null }
817: 
818:     if (-not $bridgeOutcome) {
819:         if ($exitCode -ne 0) {
820:             $detail = $eventError
821:             if (-not $detail -and $stderrText) {
822:                 $detail = ($stderrText.Trim() -split "`r?`n" | Select-Object -Last 1)
823:             }
824:             $tail = ''
825:             if ($detail) { $tail = ' - ' + $detail }
826:             $bridgeOutcome = "failed: codex exit $exitCode$tail"
827:         } elseif (-not $rawReply) {
828:             $detail = ''
829:             if ($eventError) { $detail = ' - ' + $eventError }
830:             $bridgeOutcome = "failed: empty reply$detail"
831:         } else {
832:             $bridgeOutcome = 'usable reply'
833:         }
834:     }
835: 
836:     # ------------------------------------------------------------------------- structured reply
837: 
838:     # A reply that is not valid JSON or breaks the schema is NOT a bridge failure: the
839:     # raw text is kept as the reply, but there is no verdict and no finding is recorded.
840:     $structured = $false
841:     $parse = $null
842:     $ingest = $null
843:     $validationError = ''
844:     $verdict = ''
845:     $verdictReason = ''
846:     $replyBody = $rawReply
847:     $counts = [pscustomobject]@{ blocker = 0; major = 0; minor = 0; note = 0 }
848:     $findingIds = @()
849:     $priorForLedger = @()
850:     if (-not $Raw -and $bridgeOutcome -eq 'usable reply') {
851:         $parse = ConvertFrom-StructuredReply -Text $rawReply
852:         $validationError = $parse.ValidationError
853:         if ($parse.Valid) {
854:             $structured = $true
855:             $replyBody = $parse.Reply.reply_markdown
856:             $verdict = $parse.Verdict
857:             if (-not $parse.Contradiction) { $verdictReason = $parse.Reply.verdict_reason }
858:             $ingest = Add-ReplyFindings -Store $findingsStore -Reply $parse.Reply -Nn $nn -ConsultN $consultN `
859:                 -ReplyRel $replyRel -ThreadId $threadId -BaseCommit $revBefore.base_commit `
860:                 -TreeSha256 $revBefore.tree_sha256 -ListedIds $listedIds
861:             $counts = $ingest.Counts
862:             $findingIds = @($ingest.NewIds)
863:             $priorForLedger = @($ingest.PriorEntries | ForEach-Object { [pscustomobject]@{ id = $_.id; status = $_.status } })
864:         }
865:     }
866:     $replyJsonRel = ''
867:     if (-not $Raw -and (Test-Path -LiteralPath $lastMsgPath -PathType Leaf)) { $replyJsonRel = $replyJsonPlanned }
868:

438: function New-FindingsStore {
439:     param([string]$Task)
440:     return [pscustomobject]@{ task_id = $Task; findings = [object[]]@() }
441: }
442: 
443: function Read-FindingsFile {
444:     param([string]$Path, [string]$Task)
445:     if (-not (Test-Path -LiteralPath $Path)) { return (New-FindingsStore -Task $Task) }
446:     $text = Read-SharedText -Path $Path
447:     if (-not $text.Trim()) { return (New-FindingsStore -Task $Task) }
448:     $data = $null
449:     try { $data = ConvertFrom-Json -InputObject $text } catch {
450:         Stop-WithError "could not parse '$Path': $($_.Exception.Message)"
451:     }
452:     if (-not ($data -is [System.Management.Automation.PSCustomObject])) {
453:         Stop-WithError "'$Path' is not a findings file (expected a JSON object with a findings array)."
454:     }
455:     if (-not $data.PSObject.Properties['findings']) {
456:         $data | Add-Member -NotePropertyName 'findings' -NotePropertyValue ([object[]]@())
457:     }
458:     $data.findings = [object[]]@($data.findings | Where-Object { $null -ne $_ })
459:     return $data
460: }
461: 
462: function Write-FindingsFile {
463:     param([string]$Path, $Store)
464:     $Store.findings = [object[]]@($Store.findings | Where-Object { $null -ne $_ })
465:     Write-JsonFile -Path $Path -Object $Store
466: }
