468: function Get-PropertyValue {
469:     param($Object, [string]$Name, $Default = '')
470:     if ($null -ne $Object -and $Object.PSObject.Properties[$Name] -and $null -ne $Object.$Name) { return $Object.$Name }
471:     return $Default
472: }
473: 
474: # Appends $Item to the array property $Name of $Object (creating it when missing) and
475: # keeps the value an [object[]] - a one-element array must stay an array in JSON.
476: function Add-ArrayItem {
477:     param($Object, [string]$Name, $Item)
478:     if ($Object.PSObject.Properties[$Name]) {
479:         $existing = @($Object.$Name | Where-Object { $null -ne $_ })
480:         $Object.$Name = [object[]]($existing + @($Item))
481:     } else {
482:         $Object | Add-Member -NotePropertyName $Name -NotePropertyValue ([object[]]@($Item))
483:     }
484: }
