838: function Add-ReplyFindings {
839:     param(
840:         $Store,
841:         $Reply,
842:         [string]$Nn,
843:         [int]$ConsultN,
844:         [string]$ReplyRel,
845:         [string]$ThreadId,
846:         [string]$BaseCommit,
847:         [string]$TreeSha256,
848:         [string[]]$ListedIds = @(),
849:         [string]$When = ''
850:     )
851:     if (-not $When) { $When = Get-IsoTimestamp }
852:     $existing = @{}
853:     foreach ($f in @($Store.findings)) {
854:         if ($null -ne $f -and $f.PSObject.Properties['id']) { $existing[[string]$f.id] = $f }
855:     }
856:     $newIds = New-Object System.Collections.Generic.List[string]
857:     $newRecords = New-Object System.Collections.Generic.List[object]
858:     $k = 0
859:     foreach ($f in @($Reply.findings)) {
860:         $k++
861:         $id = "F$Nn-$k"
862:         $newIds.Add($id)
863:         $newRecords.Add([pscustomobject]@{
864:                 id              = $id
865:                 status          = 'proposed'
866:                 severity        = $f.severity
867:                 locations       = [object[]]@($f.locations)
868:                 claim           = $f.claim
869:                 trigger         = $f.trigger
870:                 evidence        = [object[]]@($f.evidence)
871:                 verification    = $f.verification
872:                 remedy          = $f.remedy
873:                 supersedes      = [object[]]@($f.supersedes)
874:                 superseded_by   = [object[]]@()
875:                 source          = [pscustomobject]@{
876:                     consult     = $ConsultN
877:                     reply       = $ReplyRel
878:                     thread      = $ThreadId
879:                     base_commit = $BaseCommit
880:                     tree_sha256 = $TreeSha256
881:                 }
882:                 history         = [object[]]@([pscustomobject]@{
883:                         when        = $When
884:                         status      = 'proposed'
885:                         by          = 'codex-consult'
886:                         note        = ''
887:                         evidence    = ''
888:                         base_commit = $BaseCommit
889:                         tree_sha256 = $TreeSha256
890:                     })
891:                 reviewer_checks = [object[]]@()
892:             })
893:     }
894:     $changed = ($newRecords.Count -gt 0)
895: 
896:     $unknownSupersedes = New-Object System.Collections.Generic.List[string]
897:     foreach ($rec in $newRecords) {
898:         foreach ($old in @($rec.supersedes)) {
899:             if ($existing.ContainsKey([string]$old)) {
900:                 $target = $existing[[string]$old]
901:                 $already = @(Get-PropertyValue $target 'superseded_by' @()) -contains $rec.id
902:                 if (-not $already) { Add-ArrayItem -Object $target -Name 'superseded_by' -Item $rec.id; $changed = $true }
903:             } else {
904:                 $unknownSupersedes.Add([string]$old)
905:             }
906:         }
907:     }
908: 
909:     $priorEntries = New-Object System.Collections.Generic.List[object]
910:     $unknownIds = New-Object System.Collections.Generic.List[string]
911:     $reported = @{}
912:     foreach ($p in @($Reply.prior_findings)) {
913:         $priorId = [string]$p.id
914:         $reported[$priorId] = $true
915:         $known = $existing.ContainsKey($priorId)
916:         $priorEntries.Add([pscustomobject]@{ id = $priorId; status = $p.status; note = $p.note; known = $known })
917:         if ($known) {
918:             Add-ArrayItem -Object $existing[$priorId] -Name 'reviewer_checks' -Item ([pscustomobject]@{
919:                     consult     = $ConsultN
920:                     when        = $When
921:                     status      = $p.status
922:                     note        = $p.note
923:                     base_commit = $BaseCommit
924:                     tree_sha256 = $TreeSha256
925:                 })
926:             $changed = $true
927:         } else {
928:             $unknownIds.Add($priorId)
929:         }
930:     }
931:     $notReported = New-Object System.Collections.Generic.List[string]
932:     foreach ($listed in @($ListedIds | Where-Object { $_ })) {
933:         if ($reported.ContainsKey($listed) -or -not $existing.ContainsKey($listed)) { continue }
934:         $notReported.Add($listed)
935:         $priorEntries.Add([pscustomobject]@{ id = $listed; status = 'not-checked'; note = '(not reported)'; known = $true })
936:         Add-ArrayItem -Object $existing[$listed] -Name 'reviewer_checks' -Item ([pscustomobject]@{
937:                 consult     = $ConsultN
938:                 when        = $When
939:                 status      = 'not-checked'
940:                 note        = '(not reported)'
941:                 base_commit = $BaseCommit
942:                 tree_sha256 = $TreeSha256
943:             })
944:         $changed = $true
945:     }
946: 
947:     if ($newRecords.Count -gt 0) {
948:         $Store.findings = [object[]](@($Store.findings | Where-Object { $null -ne $_ }) + $newRecords.ToArray())
949:     }
950:     return [pscustomobject]@{
951:         NewIds            = [string[]]$newIds.ToArray()
952:         PriorEntries      = [object[]]$priorEntries.ToArray()
953:         UnknownIds        = [string[]]$unknownIds.ToArray()
954:         NotReported       = [string[]]$notReported.ToArray()
955:         UnknownSupersedes = [string[]]$unknownSupersedes.ToArray()
956:         Counts            = (Get-SeverityCounts -Findings $Reply.findings)
957:         Changed           = $changed
