990: function Format-StructuredSection {
991:     param($Parse, $Ingest)
992:     $r = $Parse.Reply
993:     $ids = @($Ingest.NewIds)
994:     $out = New-Object System.Collections.Generic.List[string]
995: 
996:     $out.Add('### Findings')
997:     $out.Add('')
998:     $findings = @($r.findings)
999:     if ($findings.Count -eq 0) { $out.Add('_(none)_') }
1000:     for ($i = 0; $i -lt $findings.Count; $i++) {
1001:         $f = $findings[$i]
1002:         $line = "- **$($ids[$i])** [$($f.severity)] $(Format-Locations -Locations $f.locations -Code) - $(Close-Sentence $f.claim)"
1003:         if ($f.trigger) { $line += " Trigger: $(Close-Sentence $f.trigger)" }
1004:         $ev = @(foreach ($e in @($f.evidence)) { "$($e.kind): $(ConvertTo-OneLine $e.observation)" })
1005:         if ($ev.Count -gt 0) { $line += " Evidence: $(Close-Sentence ($ev -join '; '))" }
1006:         if ($f.verification) { $line += " Verify: $(Close-Sentence $f.verification)" }
1007:         if ($f.remedy) { $line += " Remedy: $(Close-Sentence $f.remedy)" }
1008:         $sup = @($f.supersedes | Where-Object { $_ })
1009:         if ($sup.Count -gt 0) { $line += " Supersedes: $($sup -join ', ')." }
1010:         $out.Add($line)
1011:     }
1012:     $out.Add('')
1013: 
1014:     $out.Add('### Prior findings')
1015:     $out.Add('')
1016:     $prior = @($Ingest.PriorEntries)
1017:     if ($prior.Count -eq 0) { $out.Add('_(none)_') }
1018:     foreach ($p in $prior) {
1019:         $line = "- $($p.id) - $($p.status)"
1020:         $note = ConvertTo-OneLine $p.note
1021:         if ($note) { $line += " - $note" }
1022:         if (-not $p.known) { $line += ' _(unknown id: not in findings.json, ignored)_' }
1023:         $out.Add($line)
1024:     }
1025:     $out.Add('')
1026: 
1027:     if ($Parse.Contradiction) {
1028:         $out.Add("## Verdict: (invalid: ACCEPT contradicts $($Parse.BlockerCount) blocker)")
1029:         $out.Add('')
1030:         $why = 'Codex answered ACCEPT'
1031:         $reason = ConvertTo-OneLine $r.verdict_reason
1032:         if ($reason) { $why += " ($reason)" }
1033:         $out.Add("$why, but the reply lists blocker findings; no verdict was recorded.")
1034:     } else {
1035:         $out.Add("## Verdict: $($Parse.Verdict)")
1036:         $out.Add('')
1037:         $reason = ConvertTo-OneLine $r.verdict_reason
1038:         if (-not $reason) { $reason = '_(no reason given)_' }
1039:         $out.Add($reason)
1040:     }
1041:     $out.Add('')
1042: 
1043:     $out.Add('### Blockers')
1044:     $out.Add('')
1045:     $nb = 0
1046:     for ($i = 0; $i -lt $findings.Count; $i++) {
1047:         $f = $findings[$i]
1048:         if ($f.severity -ne 'blocker') { continue }
1049:         $nb++
1050:         $line = "- **$($ids[$i])** $(Format-Locations -Locations $f.locations -Code) - $(Close-Sentence $f.claim)"
1051:         if ($f.verification) { $line += " Verify: $(Close-Sentence $f.verification)" }
1052:         if ($f.remedy) { $line += " Remedy: $(Close-Sentence $f.remedy)" }
1053:         $out.Add($line)
1054:     }
1055:     if ($nb -eq 0) { $out.Add('_(none)_') }
1056:     $out.Add('')
1057: 
1058:     $out.Add('### Unproven scenarios')
1059:     $out.Add('')
1060:     $un = @($r.unproven | Where-Object { $_ })
1061:     if ($un.Count -eq 0) { $out.Add('_(none)_') }
1062:     foreach ($u in $un) { $out.Add("- $(ConvertTo-OneLine $u)") }
1063:     $out.Add('')
1064: 
1065:     $out.Add('### First-run checklist (observable)')
1066:     $out.Add('')
1067:     $cl = @($r.first_run_checklist | Where-Object { $_ })
1068:     if ($cl.Count -eq 0) { $out.Add('_(none)_') }
1069:     foreach ($c in $cl) { $out.Add("- [ ] $(ConvertTo-OneLine $c)") }
1070: 
1071:     return ($out.ToArray() -join "`n")
1072: }
