576: function Test-StructuredReply {
577:     param($Reply)
578:     $errors = New-Object System.Collections.Generic.List[string]
579:     if (-not (Test-IsJsonObject $Reply)) {
580:         $errors.Add('the reply is not a JSON object')
581:         return , ([string[]]$errors.ToArray())
582:     }
583:     $names = @($Reply.PSObject.Properties | ForEach-Object { $_.Name })
584:     foreach ($f in $script:ReplyFields) {
585:         if ($names -notcontains $f) { $errors.Add("missing field '$f'") }
586:     }
587:     foreach ($n in $names) {
588:         if ($script:ReplyFields -cnotcontains $n) { $errors.Add("unexpected field '$n'") }
589:     }
590:     if ($errors.Count -gt 0) { return , ([string[]]$errors.ToArray()) }
591: 
592:     if (-not (Test-IsJsonString $Reply.schema_version) -or [string]$Reply.schema_version -cne '1') {
593:         $errors.Add("schema_version must be ""1"" (got '$($Reply.schema_version)')")
594:     }
595:     if (-not (Test-IsJsonString $Reply.verdict) -or $script:Verdicts -cnotcontains [string]$Reply.verdict) {
596:         $errors.Add("verdict '$($Reply.verdict)' is not one of $($script:Verdicts -join '|')")
597:     }
598:     foreach ($f in @('verdict_reason', 'reply_markdown')) {
599:         if (-not (Test-IsJsonString $Reply.$f)) { $errors.Add("$f is not a string") }
600:     }
601:     foreach ($f in @('unproven', 'first_run_checklist')) {
602:         if (-not (Test-IsJsonArray $Reply.$f)) { $errors.Add("$f is not an array"); continue }
603:         $k = 0
604:         foreach ($item in $Reply.$f) {
605:             if (-not (Test-IsJsonString $item)) { $errors.Add("$f[$k] is not a string") }
606:             $k++
607:         }
608:     }
609: 
610:     if (-not (Test-IsJsonArray $Reply.findings)) {
611:         $errors.Add('findings is not an array')
612:     } else {
613:         $k = 0
614:         foreach ($fd in $Reply.findings) {
615:             $at = "findings[$k]"
616:             $k++
617:             if (-not (Test-IsJsonObject $fd)) { $errors.Add("$at is not an object"); continue }
618:             $fnames = @($fd.PSObject.Properties | ForEach-Object { $_.Name })
