630:             foreach ($f in @('claim', 'trigger', 'verification', 'remedy')) {
631:                 if (-not (Test-IsJsonString $fd.$f)) { $errors.Add("$at.$f is not a string") }
632:             }
633:             if (-not (Test-IsJsonArray $fd.locations)) {
634:                 $errors.Add("$at.locations is not an array")
635:             } else {
636:                 $j = 0
637:                 foreach ($l in $fd.locations) {
