710: function ConvertTo-NormalizedReply {
711:     param($Reply)
712:     $findings = @(foreach ($fd in $Reply.findings) {
713:             [pscustomobject]@{
714:                 severity     = [string]$fd.severity
715:                 locations    = [object[]]@(foreach ($l in $fd.locations) {
716:                         $line = $null
717:                         if ($null -ne $l.line) { $line = [long]$l.line }
718:                         [pscustomobject]@{ path = (ConvertTo-JsonText $l.path); line = $line }
719:                     })
720:                 claim        = (ConvertTo-JsonText $fd.claim)
721:                 trigger      = (ConvertTo-JsonText $fd.trigger)
722:                 evidence     = [object[]]@(foreach ($ev in $fd.evidence) {
723:                         [pscustomobject]@{ kind = [string]$ev.kind; reference = (ConvertTo-JsonText $ev.reference); observation = (ConvertTo-JsonText $ev.observation) }
724:                     })
725:                 verification = (ConvertTo-JsonText $fd.verification)
726:                 remedy       = (ConvertTo-JsonText $fd.remedy)
727:                 supersedes   = [object[]]@(foreach ($s in $fd.supersedes) { ConvertTo-JsonText $s })
728:             }
729:         })
730:     $prior = @(foreach ($pf in $Reply.prior_findings) {
731:             [pscustomobject]@{ id = (ConvertTo-JsonText $pf.id); status = [string]$pf.status; note = (ConvertTo-JsonText $pf.note) }
732:         })
733:     return [pscustomobject]@{
734:         schema_version      = '1'
735:         verdict             = [string]$Reply.verdict
736:         verdict_reason      = (ConvertTo-JsonText $Reply.verdict_reason)
737:         reply_markdown      = (ConvertTo-JsonText $Reply.reply_markdown)
738:         findings            = [object[]]$findings
739:         prior_findings      = [object[]]$prior
740:         unproven            = [object[]]@(foreach ($u in $Reply.unproven) { ConvertTo-JsonText $u })
741:         first_run_checklist = [object[]]@(foreach ($c in $Reply.first_run_checklist) { ConvertTo-JsonText $c })
742:     }
743: }
744: 
745: # Parses Codex's last message in structured mode. Tolerates a ```json fence around
746: # the object. Outcomes (amendment M2):
747: #   Valid=$false          not JSON, or any structural error: ValidationError = the
748: #                         first error, no verdict, the caller records no findings
749: #   Valid, Contradiction  verdict ACCEPT with blocker findings: findings are ingested,
750: #                         Verdict '' and ValidationError says why
751: #   Valid                 Verdict = the reply's verdict
752: function ConvertFrom-StructuredReply {
753:     param([string]$Text)
754:     $result = [pscustomobject]@{
755:         Valid           = $false
756:         Reply           = $null
757:         Errors          = [string[]]@()
758:         ValidationError = ''
759:         Verdict         = ''
760:         Contradiction   = $false
761:         BlockerCount    = 0
762:         Fenced          = $false
763:     }
764:     $t = ''
765:     if ($Text) { $t = $Text.Trim() }
766:     if (-not $t) {
767:         $result.ValidationError = 'empty reply'
768:         $result.Errors = [string[]]@('empty reply')
769:         return $result
770:     }
771:     $fence = [regex]::Match($t, '^```[A-Za-z0-9_-]*[ \t]*\r?\n(?<body>[\s\S]*?)\r?\n[ \t]*```$')
772:     if ($fence.Success) { $t = $fence.Groups['body'].Value.Trim(); $result.Fenced = $true }
773:     $obj = $null
774:     try {
775:         $obj = ConvertFrom-Json -InputObject $t
776:     } catch {
777:         $msg = ConvertTo-OneLine $_.Exception.Message
778:         if ($msg.Length -gt 120) { $msg = $msg.Substring(0, 120) + '...' }
779:         $result.ValidationError = "not valid JSON: $msg"
780:         $result.Errors = [string[]]@($result.ValidationError)
781:         return $result
782:     }
783:     $errs = Test-StructuredReply -Reply $obj
784:     if ($errs.Count -gt 0) {
785:         $result.Errors = $errs
786:         $result.ValidationError = $errs[0]
787:         return $result
788:     }
789:     $norm = ConvertTo-NormalizedReply -Reply $obj
790:     $result.Valid = $true
791:     $result.Reply = $norm
792:     $blockers = @($norm.findings | Where-Object { $_.severity -eq 'blocker' }).Count
793:     $result.BlockerCount = $blockers
794:     if ($norm.verdict -eq 'ACCEPT' -and $blockers -gt 0) {
795:         $result.Contradiction = $true
796:         $result.ValidationError = "verdict ACCEPT contradicts $blockers blocker finding(s)"
797:         $result.Verdict = ''
798:     } else {
799:         $result.Verdict = $norm.verdict
800:     }
801:     return $result
802: }
803: 
804: function Get-SeverityCounts {
228: # ----------------------------------------------------------------------------- -Id -Status
229: 
230: if (-not (Test-Path -LiteralPath $findingsPath)) {
231:     Stop-WithError "no findings recorded for task '$Task' ($findingsPath does not exist)."
232: }
233: 
234: $lock = Enter-TaskLock -TaskDir $taskDir -Task $Task
235: if (-not $lock.Acquired) { Stop-WithError $lock.Message }
236: if ($lock.Note) { Write-Host "codex-findings: $($lock.Note)" -ForegroundColor Yellow }
237: try {
238:     $store = Read-FindingsFile -Path $findingsPath -Task $Task
239:     $target = $null
240:     foreach ($f in @($store.findings)) {
241:         if ([string](Get-PropertyValue $f 'id' '') -eq $Id.Trim()) { $target = $f; break }
242:     }
243:     if (-not $target) {
244:         Stop-WithError "unknown finding id '$Id' in $findingsPath (codex-findings.ps1 -Task $Task -List -All shows every id)."
245:     }
246:     $current = [string](Get-PropertyValue $target 'status' '')
247:     if ($Status -eq 'proposed' -and $current -ne 'proposed' -and -not $Note.Trim()) {
248:         Stop-WithError "reopening $($target.id) ($current -> proposed) requires -Note (why it is open again)."
249:     }
250: 
251:     $rev = Get-RevisionInfo -Root $repoRoot -CollabRoot $collabRoot
252:     $record = [pscustomobject]@{
253:         when        = (Get-IsoTimestamp)
254:         status      = $Status
255:         by          = 'coordinator'
256:         note        = $Note.Trim()
257:         evidence    = $Evidence.Trim()
258:         base_commit = $rev.base_commit
259:         tree_sha256 = $rev.tree_sha256
260:     }
261:     Add-ArrayItem -Object $target -Name 'history' -Item $record
262:     if ($target.PSObject.Properties['status']) { $target.status = $Status }
263:     else { $target | Add-Member -NotePropertyName 'status' -NotePropertyValue $Status }
264:     Write-FindingsFile -Path $findingsPath -Store $store
265: 
266:     Write-Host "codex-findings: $($target.id) $current -> $Status (history: $(@($target.history).Count) records; tree sha256 $(if ($rev.tree_sha256) { $rev.tree_sha256.Substring(0, 12) } else { 'none (no git)' }))."
267:     Write-Host (Format-FindingLine -Finding $target)
268:     exit 0
269: } finally {
270:     Exit-TaskLock -Lock $lock
271: }

